function popText(text,x,y,punch=false){const el=document.createElement('div');el.className='float'+(punch?' punch':'');el.textContent=text;el.style.left=`${x}px`;el.style.top=`${y}px`;document.body.appendChild(el);setTimeout(()=>el.remove(),1000)}
function startBoss(level,costPaid){const boss=BOSSES[level];if(!boss)return;state.bossActive=true;state.bossLevel=level;state.bossCostPaid=costPaid;state.baseLevel=level+2;state.bossMax=boss.hp;state.bossHP=boss.hp;state.bossTimeLeft=boss.time;render();notify(`${boss.name} ATACOU! DEFENDA SUA BASE!`);popText('BOSS!',window.innerWidth*.34,window.innerHeight*.36,true);save()}
function finishBoss(won){const level=state.bossLevel,boss=BOSSES[level]||BOSSES[0],paid=state.bossCostPaid;state.bossActive=false;state.bossTimeLeft=0;if(won){const reward=Math.round((35+passive()*8)*(1+level*.35));state.credits+=reward;state.totalEarned+=reward;state.bossCostPaid=0;state.bossHP=0;notify(`${boss.name} DERROTADO! BASE NO NÍVEL ${state.baseLevel}!`);popText('POW! +'+compact(reward),window.innerWidth*.35,window.innerHeight*.4,true)}else{state.baseLevel=level+1;let lost=level+2;for(const hero of [...DATA.heroes].reverse()){const removed=Math.min(count(hero.id),lost);state.counts[hero.id]=count(hero.id)-removed;lost-=removed;if(lost<=0)break}const lostTotal=level+2-lost;state.bossHP=0;state.bossCostPaid=0;notify(`${boss.name} VENCEU! Upgrade perdido (${compact(paid)}) e ${lostTotal} herói(s) abatido(s).`);popText(`DERROTA · −${lostTotal} HERÓIS`,window.innerWidth*.35,window.innerHeight*.4,true)}render();save()}
function collect(){const now=Date.now();const btn=$('alertButton'),rect=btn.getBoundingClientRect();if(state.bossActive){state.bossHP=Math.max(0,state.bossHP-clickPower());popText('👊 -'+compact(clickPower()),rect.left+rect.width*(.3+Math.random()*.4),rect.top-8,true);$('city').classList.remove('shake');void $('city').offsetWidth;$('city').classList.add('shake');if(state.bossHP<=0)finishBoss(true);else render();return}if(now-state.lastClick<900)state.combo=Math.min(20,state.combo+1);else state.combo=0;state.lastClick=now;const comboMultiplier=Math.min(5,1+Math.floor(state.combo/5));const amount=clickPower()*comboMultiplier;state.credits+=amount;state.totalEarned+=amount;popText(state.combo>0&&state.combo%5===0?'👊 POW!':`👊 +${compact(amount)}`,rect.left+rect.width*(.3+Math.random()*.4),rect.top-8,true);$('city').classList.remove('shake');void $('city').offsetWidth;$('city').classList.add('shake');render();}
let lastFrame=performance.now(),missionElapsed=0;
function tick(now){const dt=Math.min((now-lastFrame)/1000,1);lastFrame=now;const income=passive()*dt;state.credits+=income;state.totalEarned+=income;if(state.bossActive){state.bossTimeLeft-=dt;if(state.bossTimeLeft<=0)finishBoss(false)}else{missionElapsed+=dt;const duration=missionDuration();if(missionElapsed>=duration){missionElapsed%=duration;const reward=missionReward();state.credits+=reward;state.totalEarned+=reward;state.mission++;popText('👊 +'+compact(reward),window.innerWidth*.35,window.innerHeight*.48,false)}$('missionTimer').textContent=`próxima em ${Math.ceil(duration-missionElapsed)}s`;$('missionProgress').style.width=`${Math.max(0,(1-missionElapsed/duration)*100)}%`}if(state.bossActive)updateBoss();if(Math.floor(now/200)!==Math.floor((now-dt*1000)/200))render();requestAnimationFrame(tick)}
document.querySelectorAll('.tab').forEach(button=>button.addEventListener('click',()=>{document.querySelector('.tab.active').classList.remove('active');button.classList.add('active');currentTab=button.dataset.tab;renderShop()}));$('alertButton').addEventListener('click',collect);window.addEventListener('keydown',e=>{if((e.code==='Space'||e.code==='Enter')&&!e.repeat&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();collect()}});$('offlineClose').addEventListener('click',()=>{$('offlineOverlay').classList.remove('show');save()});document.addEventListener('visibilitychange',()=>{if(document.hidden)save()});window.addEventListener('beforeunload',save);
load();render();requestAnimationFrame(tick);setInterval(save,5000);
</script>
