];
let state={credits:0,counts:{},clickLevels:{},last:Date.now(),totalEarned:0,combo:0,lastClick:0,mission:0,bossActive:false,bossHP:0,bossMax:0,bossTimeLeft:0,baseLevel:1,bossLevel:0,bossCostPaid:0};
let currentTab='heroes',toastTimer,sceneSignature='';
const $=id=>document.getElementById(id);
const compact=n=>{if(n>=1e12)return (n/1e12).toFixed(2)+'T';if(n>=1e9)return (n/1e9).toFixed(2)+'B';if(n>=1e6)return (n/1e6).toFixed(2)+'M';if(n>=1e4)return (n/1e3).toFixed(1)+'K';return Math.floor(n).toLocaleString('pt-BR')};
const allItems=()=>[...DATA.heroes,...DATA.vehicles,...DATA.gear,...shopItems()];
const count=id=>state.counts[id]||0;
function shopItems(){if(currentTab==='base'){const index=state.bossActive?state.bossLevel:state.baseLevel-1;return state.bossActive||index<BASE_COSTS.length?[{id:'baseUpgrade',name:state.bossActive?'Defesa da Base':'Upgrade de Base',icon:state.bossActive?'⚠️':'🏙️',desc:state.bossActive?`${BOSSES[index].name} está atacando! Derrote-o antes que o tempo acabe.`:`Evolua para a Base nível ${state.baseLevel+1} e enfrente ${BOSSES[index].name}.`,baseCost:state.bossActive?state.bossCostPaid:BASE_COSTS[index],growth:1,base:true}]:[]}return DATA[currentTab]||[]}
function baseMultiplier(){return Math.pow(1.15,Math.max(0,state.baseLevel-1))}
function passive(){let base=DATA.heroes.reduce((sum,item)=>sum+count(item.id)*item.gps,0);return base*multiplier()*baseMultiplier()}
function multiplier(){return 1+DATA.gear.filter(i=>i.mult).reduce((s,i)=>s+count(i.id)*i.mult,0)}
function missionDuration(){return Math.max(3,10-DATA.vehicles.reduce((s,i)=>s+count(i.id)*(i.bonus?i.bonus*14:0),0))}
function missionReward(){return Math.max(5,Math.round((5+passive()*.45)*(1+Math.log10(1+state.totalEarned/1000)*.15)))}
function clickPower(){return 1+DATA.gear.filter(i=>i.click).reduce((s,i)=>s+count(i.id)*i.click,0)}
function repLevel(){return Math.max(1,Math.floor(Math.sqrt(state.totalEarned/250))+1)}
function teamCount(){return DATA.heroes.reduce((s,i)=>s+count(i.id),0)}
function save(){state.last=Date.now();try{localStorage.setItem(SAVE_KEY,JSON.stringify(state))}catch(e){}}
function load(){try{const raw=localStorage.getItem(SAVE_KEY);if(raw){const parsed=JSON.parse(raw);state={...state,...parsed};state.counts=state.counts||{};state.clickLevels=state.clickLevels||{};if(state.bossActive&&(!Object.prototype.hasOwnProperty.call(parsed,'bossCostPaid')||!state.bossCostPaid)){state.bossActive=false;state.bossHP=0;state.bossTimeLeft=0;state.bossCostPaid=0;state.baseLevel=Math.max(1,state.baseLevel||1)}state.baseLevel=Math.max(1,Math.min(BASE_COSTS.length+1,state.baseLevel||1));state.bossLevel=Math.max(0,Math.min(BOSSES.length-1,state.bossLevel||0));const away=Math.max(0,Math.min(8*3600,(Date.now()-(state.last||Date.now()))/1000));const earned=passive()*away;state.credits+=earned;state.totalEarned+=earned;if(earned>=1){$('offlineEarned').textContent='+'+compact(earned)+' créditos';$('offlineOverlay').classList.add('show')}}}catch(e){console.warn('Save indisponível',e)}}
function cost(item){if(item.base)return item.baseCost;const n=item.id in state.counts?count(item.id):0;return Math.ceil(item.baseCost*Math.pow(item.growth,n))}
function unlocked(item){return item.base?(state.bossActive||state.baseLevel<=BASE_COSTS.length):state.baseLevel>=(item.baseUnlock||1)&&(state.totalEarned>=item.unlock||count(item.id)>0)}
function lockedDescription(item){return item.baseUnlock&&state.baseLevel<item.baseUnlock?`Desbloqueia na Base nível ${item.baseUnlock}`:`Desbloqueia com ${compact(item.unlock)} créditos acumulados`}
function renderShop(){const collection=shopItems();const headings={heroes:['Monte sua equipe','Recrute heróis para gerar créditos por segundo.'],vehicles:['Expanda sua garagem','Veículos aceleram as missões automáticas.'],gear:['Tecnologia de ponta','Aprimore alertas e renda da equipe.'],base:['Evolua sua base','Cada upgrade inicia um confronto decisivo.']};const tally=currentTab==='base'?`NÍVEL ${state.baseLevel}`:`${collection.reduce((s,i)=>s+count(i.id),0)} ADQUIRIDOS`;let html=`<div class="shop-head"><div><h2>${headings[currentTab][0]}</h2><p>${headings[currentTab][1]}</p></div><span class="count">${tally}</span></div><div class="items">`;if(currentTab==='base'&&!collection.length)html+='<article class="item"><div class="item-icon">🏆</div><div class="item-copy"><div class="item-name">Base no nível máximo</div><div class="item-desc">A cidade está pronta para qualquer ameaça.</div><div class="item-level">TODOS OS CINCO CHEFES DERROTADOS</div></div></article>';

 for(const item of collection){const n=count(item.id),price=cost(item),available=unlocked(item),canBuy=state.credits>=price&&available&&!state.bossActive;let value=item.base?`CHEFE: ${BOSSES[state.bossActive?state.bossLevel:state.baseLevel-1].name} · RISCO: ${state.bossActive?state.bossLevel+2:state.baseLevel} HERÓIS`:item.gps?`+${compact(item.gps)} créditos/s cada`:item.click?`+${item.click} por alerta / nível`:item.mult?`+${Math.round(item.mult*100)}% renda / nível`:`−${Math.round(item.bonus*100)}% tempo de missão`;html+=`<article class="item ${available?'':'locked'}" data-item="${item.id}"><div class="item-icon">${available?item.icon:'🔒'}</div><div class="item-copy"><div class="item-name">${available?item.name:'???'}</div><div class="item-desc">${available?item.desc:lockedDescription(item)}</div><div class="item-level">${available?(item.base?(state.bossActive?`CONFRONTO ATIVO · UPGRADE ${compact(state.bossCostPaid)}`:`BASE ${state.baseLevel} → ${state.baseLevel+1}`):`${value} · NÍVEL ${n}`):'PROGRESSO BLOQUEADO'}</div></div><button class="buy" data-buy="${item.id}" ${canBuy?'':'disabled'}>${available?`−${compact(price)}<small>CRÉDITOS</small>`:'BLOQUEADO'}</button></article>`}
 $('shop').innerHTML=html+'</div>';
 $('shop').querySelectorAll('[data-buy]').forEach(button=>button.addEventListener('click',()=>purchase(button.dataset.buy)));
}
function refreshShop(){const collection=shopItems(),cards=[...$('shop').querySelectorAll('.item')];if(cards.length!==collection.length+(currentTab==='base'&&!collection.length?1:0)||collection.some((item,index)=>cards[index]?.dataset.item!==item.id)){renderShop();return}const countLabel=$('shop').querySelector('.shop-head .count');if(countLabel)countLabel.textContent=currentTab==='base'?`NÍVEL ${state.baseLevel}`:`${collection.reduce((s,item)=>s+count(item.id),0)} ADQUIRIDOS`;for(const item of collection){const card=$('shop').querySelector(`[data-item="${item.id}"]`),available=unlocked(item),price=cost(item),n=count(item.id);const value=item.base?`CHEFE: ${BOSSES[state.bossActive?state.bossLevel:state.baseLevel-1].name} · RISCO: ${state.bossActive?state.bossLevel+2:state.baseLevel} HERÓIS`:item.gps?`+${compact(item.gps)} créditos/s cada`:item.click?`+${item.click} por alerta / nível`:item.mult?`+${Math.round(item.mult*100)}% renda / nível`:`−${Math.round(item.bonus*100)}% tempo de missão`;card.classList.toggle('locked',!available);card.querySelector('.item-icon').textContent=available?item.icon:'🔒';card.querySelector('.item-name').textContent=available?item.name:'???';card.querySelector('.item-desc').textContent=available?item.desc:lockedDescription(item);card.querySelector('.item-level').textContent=available?(item.base?(state.bossActive?`CONFRONTO ATIVO · UPGRADE ${compact(state.bossCostPaid)}`:`BASE ${state.baseLevel} → ${state.baseLevel+1}`):`${value} · NÍVEL ${n}`):'PROGRESSO BLOQUEADO';const button=card.querySelector('[data-buy]');button.disabled=!available||state.credits<price||state.bossActive;button.innerHTML=state.bossActive&&item.base?'EM COMBATE<small>DEFENDA A BASE</small>':available?`−${compact(price)}<small>CRÉDITOS</small>`:'BLOQUEADO'}}
function renderScene(){const signature=JSON.stringify([state.baseLevel,state.bossActive,DATA.heroes.map(item=>count(item.id)),DATA.vehicles.map(item=>count(item.id))]);if(signature===sceneSignature)return;sceneSignature=signature;const city=$('city'),base=$('base');const tier=Math.max(1,Math.min(6,state.baseLevel||1));city.className='city base-'+tier+(state.bossActive?' boss-active':'');base.className='base level-'+tier;const cityNames=['REFÚGIO URBANO • ZONA 01','CIDADE NEON • SETOR 02','FORTALEZA ARCANA • SETOR 03','COMPLEXO ORBITAL • SETOR 04','BASTIÃO VERDE • SETOR 05','CIDADE-ESTRELA • SETOR 06'];$('cityName').textContent=cityNames[tier-1];$('baseLevelTag').textContent=`BASE NÍVEL ${state.baseLevel}`;$('baseUpgrade').textContent=`⬆ BASE NÍVEL ${state.baseLevel}`;const roster=DATA.heroes.filter(item=>count(item.id)>0);if(!roster.length)roster.push({id:'rookie',name:'Recruta',icon:'🦸'});const labels={watch:'VIGIA',speed:'SPEEDSTER',titan:'TITÃ',mage:'MAGO',phoenix:'FÊNIX',rookie:'RECRUTA'};$('heroesLayer').innerHTML=roster.map((item,i)=>`<div class="hero-unit ${item.id}" style="--n:${i}" title="${item.name}"><div class="hero-cape"></div><div class="hero-head"></div><div class="hero-body">${item.icon}</div><div class="hero-legs"></div><span class="hero-tag">${labels[item.id]||item.name}</span></div>`).join('')+(teamCount()>6?`<span class="heroes-overflow">+${teamCount()-6}</span>`:'');let fleet=[];for(const item of DATA.vehicles){if(count(item.id))fleet.push(item)}if(!fleet.length)$('vehiclesLayer').innerHTML='<div class="vehicle-unit motorcycle" style="--left:68%" title="Viatura de patrulha">🚓</div>';else{let vehicles=[];fleet.forEach((item,index)=>{for(let i=0;i<Math.min(count(item.id),3);i++)vehicles.push({item,index,i})});$('vehiclesLayer').innerHTML=vehicles.map(({item,index,i})=>`<div class="vehicle-unit ${item.id}" style="--left:${54+index*14+i*5}%" title="${item.name}">${item.icon}${i===0&&count(item.id)>1?`<span class="vehicle-count">${count(item.id)}</span>`:''}</div>`).join('')}}
function updateBoss(){const active=!!state.bossActive;$('bossPanel').classList.toggle('active',active);$('alertButton').classList.toggle('boss-mode',active);$('alertButton').innerHTML=active?'<span>👊</span> DESFERIR SOCO <span class="hotkey">ESPAÇO</span>':'<span>👊</span> ATENDER CHAMADO <span class="hotkey">ESPAÇO</span>';if(active){const boss=BOSSES[state.bossLevel]||BOSSES[0];$('bossHealth').style.width=`${Math.max(0,state.bossHP/state.bossMax*100)}%`;$('bossHPText').textContent=`${Math.max(0,Math.ceil(state.bossHP))} / ${state.bossMax}`;$('bossClock').textContent=`${Math.ceil(state.bossTimeLeft)}s`;$('bossFace').textContent=boss.face;$('bossName').textContent=boss.name;$('missionName').textContent='⚠ BOSS ATACANDO A BASE';$('missionTimer').textContent=`${Math.ceil(state.bossTimeLeft)}s para derrotar`;$('missionProgress').style.width=`${Math.max(0,state.bossTimeLeft/boss.time*100)}%`;$('missionReward').textContent=`${Math.max(0,Math.ceil(state.bossHP))} pontos de vida`}else{$('missionReward').textContent=`+${compact(missionReward())}`}}
function render(){ $('credits').textContent=compact(state.credits);$('gps').innerHTML=`${compact(passive())} <small>/s</small>`;$('gpsHint').textContent=`+${Math.round((baseMultiplier()-1)*100)}% renda da base`;$('reputation').textContent=`NÍVEL ${repLevel()}`;$('repHint').textContent=repLevel()>=10?'ícone da cidade':repLevel()>=5?'defensor da metrópole':'protetores locais';$('team').innerHTML=`${teamCount()} <small>heróis</small>`;$('teamHint').textContent=teamCount()?`${teamCount()} em patrulha`:'recrute seu primeiro herói';$('clickValue').textContent=state.bossActive?`SOCO: ${compact(clickPower())} dano`:`+${compact(clickPower())} por resposta`;$('combo').textContent='x'+Math.min(5,1+Math.floor(state.combo/5));refreshShop();renderScene();updateBoss()}
function purchase(id){const item=allItems().find(i=>i.id===id);if(!item||state.bossActive)return;const price=cost(item);if(!unlocked(item)||state.credits<price)return;state.credits-=price;if(item.base){startBoss(state.baseLevel-1,price);return}state.counts[id]=count(id)+1;const label=item.gps?'RECRUTADO':item.bonus?'VEÍCULO ADQUIRIDO':'TECNOLOGIA APRIMORADA';notify(`${item.name.toUpperCase()} · ${label}!`);popText('BAM!',window.innerWidth*.68,window.innerHeight*.55,true);$('shop').classList.remove('unlock');void $('shop').offsetWidth;$('shop').classList.add('unlock');render();save()}
function notify(text){const el=$('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
