function loseBoss(){const z=zone();if(!z.boss)return;z.health=0;z.downed=true;z.credits=0;z.boss=null;$('precisionOverlay').classList.remove('show','miss');$('precisionOverlay').setAttribute('aria-hidden','true');showToast('Derrota! Você perdeu todos os créditos desta zona. Cure-se para voltar à luta.');save();render();}
 function hitBoss(damage){const z=zone();if(!z.boss||z.boss.phase!=='fight')return;const debuff=z.health<50?.5:1;z.boss.hp-=damage*debuff;if(z.boss.hp<=0){z.boss.hp=0;z.boss.phase='precision';save();beginPrecision();}else{drawScene();}}
function beginPrecision(){precisionHits=Math.max(0,Math.min(3,Number(zone().boss?.hits)||0));$('precisionOverlay').classList.add('show');$('precisionOverlay').setAttribute('aria-hidden','false');$('precisionCount').textContent=`ACERTOS ${precisionHits} / 4`;$('precisionHint').textContent='Acerte o alvo antes que ele mude. Cada erro custa 10% da sua vida.';placeTarget();updatePrecision();}
function placeTarget(){const arena=$('precisionArena'),target=$('precisionTarget');const maxX=Math.max(62,arena.clientWidth-62),maxY=Math.max(90,arena.clientHeight-45);target.style.left=`${32+Math.random()*(maxX-32)}px`;target.style.top=`${35+Math.random()*(maxY-35)}px`;}
function updatePrecision(){const hp=zone().health;$('precisionHP').textContent=`${Math.ceil(hp)}%`;$('precisionDebuff').textContent=hp<50?'DANO REDUZIDO · 50%':'DANO NORMAL';$('precisionDebuff').classList.toggle('hurt',hp<50);}
function miss(){const z=zone();if(!z.boss||z.boss.phase!=='precision')return;z.health=Math.max(0,z.health-10);const o=$('precisionOverlay');o.classList.remove('miss');void o.offsetWidth;o.classList.add('miss');if(z.health<=0){loseBoss();return;}updatePrecision();drawStats();save();}
function precisionHit(e){e.stopPropagation();const z=zone();if(!z.boss||z.boss.phase!=='precision')return;precisionHits++;z.boss.hits=precisionHits;$('precisionCount').textContent=`ACERTOS ${precisionHits} / 4`;if(precisionHits>=4){finishBoss();return;}placeTarget();save();}
function finishBoss(){const z=zone();$('precisionOverlay').classList.remove('show','miss');$('precisionOverlay').setAttribute('aria-hidden','true');z.boss=null;z.bosses++;z.bossUpgrades=(Number(z.bossUpgrades)||0)+1;z.boostUntil=Date.now()+15000;const reward=Math.floor((1200+totalPower(z)*24)*(2**state.active)*2);z.credits+=reward;z.missions++;showToast(`Vilão derrotado! Poder +10% e 2× créditos por 15s · +${fmt(reward)} CR`);save();render();}
function alertCall(){const z=zone();z.combo++;const amount=Math.max(1,Math.floor((1+z.combo*.15)*(clickPower(z)+z.base+totalPower(z)*.01)*moneyFactor(z)));z.credits+=amount;if(z.boss)hitBoss(Math.max(8,5+totalPower(z)*.08));$('combo').textContent=`x${Math.min(99,1+Math.floor(z.combo/5))}`;$('clickValue').textContent=`+${fmt(amount)} por resposta`;if(z.combo%12===0)showToast(`Combo x${1+Math.floor(z.combo/5)}!`);save();render();}
function missionTick(){const z=zone();z.missions++;const reward=Math.floor((18+z.base*9+totalPower(z)*.04)*(2**state.active)*moneyFactor(z));z.credits+=reward;$('missionReward').textContent=`+${fmt(reward)} créditos`;$('missionTimer').textContent='missão concluída';$('missionProgress').style.width='100%';if(z.missions%5===0&&!z.boss&&z.health>0&&!z.downed)startBoss();else showToast(`Missão concluída: +${fmt(reward)} créditos`);save();render();setTimeout(()=>{$('missionTimer').textContent='próxima em 10s'},1100);}
function tick(){const z=zone();z.credits+=gps(z);if(z.health>0&&!z.downed&&z.health<100)z.health=Math.min(100,z.health+healRate(z));if(z.boss&&z.boss.phase==='fight'){bossTimer++;if(bossTimer%2===0){z.health=Math.max(0,z.health-(2**state.active)*(z.health<50?3:5));if(z.health===0){loseBoss();return;}}hitBoss(Math.max(1,totalPower(z)*.04));}render();save();}
function missionProgress(){setInterval(()=>{missionElapsed++;const duration=missionDuration();$('missionTimer').textContent=`próxima em ${Math.max(0,duration-missionElapsed)}s`;$('missionProgress').style.width=`${Math.min(100,(missionElapsed/duration)*100)}%`;if(missionElapsed>=duration){missionElapsed=0;missionTick();}},1000)}
document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>{state.tab=b.dataset.tab;drawShop()}));
$('shop').addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)buy(b.dataset.action)});
$('zoneSwitch').addEventListener('click',e=>{const b=e.target.closest('[data-zone]');if(!b||b.disabled)return;$('precisionOverlay').classList.remove('show','miss');$('precisionOverlay').setAttribute('aria-hidden','true');state.active=Number(b.dataset.zone);state.tab='heroes';save();render();if(zone().boss?.phase==='precision')beginPrecision();showToast(`Defesa transferida para Zona 0${state.active+1}.`)});
$('healButton').addEventListener('click',()=>buy('heal'));$('alertButton').addEventListener('click',alertCall);$('precisionTarget').addEventListener('click',precisionHit);$('precisionArena').addEventListener('click',e=>{if(e.target!==$('precisionTarget'))miss()});$('offlineClose').addEventListener('click',()=>$('offlineOverlay').style.display='none');
document.addEventListener('keydown',e=>{if(e.code==='Space'&&!['BUTTON','INPUT'].includes(document.activeElement.tagName)&&!$('precisionOverlay').classList.contains('show')){e.preventDefault();alertCall()}});
load();render();if(zone().boss?.phase==='precision')beginPrecision();missionProgress();setInterval(tick,1000);
</script>
